import fs from 'node:fs';import crypto from 'node:crypto';const manifestPath='content/interpretation/governance/interpretation-registry-manifest-v3.json';const outPath='functions/interpretation-runtime/mir7-registry-bundle.generated.js';const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));const hash=b=>crypto.createHash('sha256').update(b).digest('hex');const manifest=read(manifestPath),registries={},hashes={};for(const [k,p] of Object.entries(manifest.registries)){const b=fs.readFileSync(p);hashes[k]=hash(b);registries[k]=JSON.parse(b.toString('utf8'));}const payload={manifestSha256:hash(fs.readFileSync(manifestPath)),registryHashes:hashes,registries};const text=`// GENERATED by scripts/build-mir-7-registry-bundle.mjs; do not hand edit.\nexport const MIR7_REGISTRY_BUNDLE = Object.freeze(${JSON.stringify(payload,null,2)});\n`;if(process.argv.includes('--check')){if(!fs.existsSync(outPath)||fs.readFileSync(outPath,'utf8')!==text){console.error('MIR-7 registry bundle drift');process.exit(1);}console.log(`✓ MIR-7 compiled registry bundle matches ${Object.keys(registries).length} canonical JSON registries.`);}else{fs.writeFileSync(outPath,text);console.log(`✓ wrote ${outPath}`);}
